INSERT INTO "public"."products" ("id", "woocommerce_id", "name", "slug", "price", "regular_price", "sale_price", "sku", "description", "short_description", "image_url", "thumbnail_url", "images", "gallery_images", "attributes", "stock_quantity", "stock_status", "manage_stock", "weight", "dimensions", "is_active", "is_featured", "is_diamond", "is_hidden_diamond", "diamond_animation_type", "has_variations", "is_variable_product", "status", "categories", "category_id", "meta_title", "meta_description", "og_image_url", "size_range_start", "size_range_end", "main_color", "created_at", "updated_at", "featured", "type", "stock", "woocommerce_category_id", "image", "virtual_weight", "purchase_price", "andre_review", "video_url", "related_product_ids", "seo_title", "seo_description", "tags", "is_pack", "pack_slots", "pack_source_category_id", "marketing_badge", "composition", "technical_documents", "tva_rate") VALUES
	('c83f53e7-f6ba-4bd8-b6a4-a1198c9caf57', NULL, 'Synergie d''Huiles Essentielles "Stimulante" – Concentration & Télétravail (10 ml)', 'synergie-d-huiles-essentielles-stimulante-concentration-teletravail-10-ml', 0, 4.9, NULL, NULL, 'L''inattendu, c''est de trouver la clé d''une concentration infaillible dans le sillage d''un parfum. Que vous soyez en journée de télétravail, en période de révision, ou face à un dossier complexe, la synergie "Stimulante" est votre nouvelle alliée productivité. Fruit d''une recherche olfactive minutieuse, ce mélange prêt à l''emploi réunit des essences naturelles spécifiquement choisies pour favoriser l''éveil intellectuel, la clarté mentale et la motivation. Diffusée près de votre espace de travail, elle dissipe le "brouillard mental" et crée une atmosphère dynamique et propice à la réflexion.<div><br></div><div>L''Exigence Kavern x Zen''Arôme : &gt; Parce que vos performances méritent un esprit clair et sain, cette synergie est fabriquée, analysée et conditionnée en France. Composée d''huiles 100% pures et naturelles (non modifiées, non diluées, non déterpénées et non reconstituées), elle est parfaitement calibrée pour une diffusion atmosphérique à froid (nébulisation ou ultrason), offrant une stimulation cérébrale tout en respectant l''intégrité absolue des plantes.</div><div><br></div><div>Détails Techniques :</div><div>​Type : Synergie (Mélange prêt à l''emploi).</div><div>​Origine : Fabriquée, analysée et conditionnée en France.</div><div>​Utilisation recommandée : Diffusion atmosphérique à froid.</div><div>​Qualité : 100% pures et naturelles.</div><div><br></div><div>​⚠️ Précautions d''utilisation : Les synergies d''huiles essentielles sont très concentrées. Tenir hors de portée des enfants. Déconseillé aux femmes enceintes ou allaitantes et aux enfants de moins de 3 ans. Ne pas ingérer. Éviter tout contact cutané pur ou avec les yeux. Ne pas diffuser le soir pour ne pas perturber le sommeil.</div>', 'Boostez votre productivité ! Ce mélange 100% pur fabriqué en France aiguise votre esprit et parfume idéalement vos journées de travail.', 'https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772114903176-i1yltg.webp', NULL, '[]', '["https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772114903130-5997ap.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772114903171-qpb49s.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772114903082-r94pc.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772114903105-lbg0m.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772114903129-plavo8.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772114903070-o7b56.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772114902643-mfd6gl.webp"]', '{"0494dad3-094b-46dc-a8da-3b5b939c1894": ["Instant Créatif", "Énergie & Réveil"], "134e714a-d9cf-41b0-8680-ec311c05d1d3": ["Huiles essentielles"], "306e8518-134c-49fd-81ea-50576a2bb9b0": ["Artisanat Français", "Création Authentique"], "52b7b1cb-e8a2-48b9-9716-087dc036c193": ["Frais & Propre"], "bac19f1b-77b1-496e-8f78-604fe43928c5": ["À moins de 10 €", "Le Coup de ❤️ d''André"]}', 3, 'instock', true, NULL, '{}', true, false, false, false, 'default', false, false, 'publish', '[]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-02-26 14:08:00.017757+00', '2026-02-26 14:12:43.312+00', false, 'simple', 0, NULL, NULL, 50, 1.85, 'C''est l''indispensable de mon bureau chez Kavern ! J''adore cette synergie car elle stimule l''intellect sans jamais énerver. C''est mon réflexe quand j''ai besoin d''être très concentré devant l''ordinateur ou de rédiger des textes importants. Mon conseil de Connaisseur : ne la diffusez pas en continu toute la journée. Allumez votre diffuseur (comme notre joli nébulisateur ''Cimio'') par tranches de 15 minutes, juste avant une réunion importante ou une session de travail profond. L''effet de clarté est immédiat !', '', '["40feca4c-8f0f-4a07-8790-4deefc6d6a05", "0db65af4-92d2-4512-8250-454dd5efd4b5", "af58d938-4278-4f6c-aef9-fb499bf348ef"]', 'Synergie Huiles Essentielles Stimulante Travail | Kavern', 'Boostez votre concentration avec la synergie Stimulante. Mélange prêt à diffuser d''huiles 100% pures. Fabriqué en France. Flacon 10ml.', '{"synergie huile essentielle","mélange pour diffusion","huile essentielle concentration","aromathérapie télétravail","synergie stimulante",Zen''Arome,"fabriqué en france","huile pour le travail"}', false, 0, NULL, NULL, NULL, NULL, 20),
	('bbcea155-8128-483d-8a74-8166173a789f', NULL, 'Fondant de Bain Effervescent "Cupcake" – 9 Parfums (Soin Hydratant)', 'fondant-de-bain-effervescent-cupcake-9-parfums-soin-hydratant', 0, 3.9, NULL, NULL, 'L''inattendu, c''est de s''offrir un soin digne d''un grand spa sous les traits de la plus irrésistible des pâtisseries. Petits bijoux pour le bain, ces fondants prennent la forme de somptueux cupcakes colorés. Leur composition unique agit en deux temps : d''abord, une base effervescente vient libérer progressivement ses arômes délicats dans l''eau chaude. Ensuite, le délicieux glaçage crémeux réalisé grâce à une technique de pochage précise fond doucement pour envelopper votre corps.<div><br></div><div>L''Exigence Kavern : &gt; Le beau s''allie à la haute cosmétique. Conçus en Europe selon un savoir-faire traditionnel d''exception, ces fondants sont intensément enrichis en beurres de cacao et de karité. Ils nourrissent, hydratent et protègent la peau en profondeur. Très généreux, la flexibilité de ce produit vous permet d''utiliser un seul fondant pour 2 bains distincts !</div><div><br></div><div>Détails Techniques :</div><div>​Format : 1 cupcake = 2 bains.</div><div>​Ingrédients phares : Beurre de cacao, Beurre de karité.</div><div>​Spécificité : Base effervescente + crème de pochage fondante.</div><div>​Origine : Conception et fabrication traditionnelle en Europe.</div><div><br></div><div>Mode d’emploi : Déposez le fondant (ou une moitié) dans une baignoire remplie d’eau tiède et laissez-le fondre pour libérer ses senteurs et ses bienfaits hydratants.</div><div>⚠️ Précautions d''utilisation : Malgré son apparence très gourmande et réaliste, ce produit n''est absolument pas comestible. Ne pas ingérer. Tenir hors de la portée des jeunes enfants. Conserver dans un endroit sec et à l’abri de la lumière pour préserver la qualité des beurres. Prenez garde en sortant de la baignoire : les beurres hydratants peuvent rendre le fond légèrement glissant.</div>', 'Succombez à la tentation ! Ces fondants façon cupcakes libèrent une base effervescente et une crème hydratante pour une peau incroyablement douce.', 'https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772288303542-zg961b.webp', NULL, '[]', '["https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772288303387-lzswve.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772288304199-nusqaa.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772288304275-g4k3t.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772288304223-k8ctbv.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772288304245-qt0hyb.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772288304242-bm7sge.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772288304232-9znzn.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772288304201-ryrs1i.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772288304198-jsovs.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772288303277-rlhjpp.webp"]', '{"PARFUM": ["royal Mango", "DELICE DE FRAISE", "CITRON ACIDULE", "LAVANDE PROVENCALE", "rose de damas", "FRUITS DE LA PASSION", "cerise", "creme fouettée/rhubarbe", "pomme d''amour"], "0494dad3-094b-46dc-a8da-3b5b939c1894": ["Détente & Spa", "Après-midi Cocooning", "Soirée Cocooning"], "306e8518-134c-49fd-81ea-50576a2bb9b0": ["Création Authentique"], "bac19f1b-77b1-496e-8f78-604fe43928c5": ["Idee cadeau", "Nouveauté"]}', 0, 'instock', false, NULL, '{}', true, false, false, false, 'default', true, false, 'publish', '[]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-02-28 14:19:15.862707+00', '2026-03-11 11:21:12.243+00', false, 'simple', 0, NULL, NULL, 60, 1.65, 'Le visuel de ces fondants est un véritable chef-d''œuvre artisanal ! Le travail de pochage de la crème et les petites finitions (les fleurs, les perles de sucre, les paillettes) en font un cadeau d''une élégance rare. Mon astuce de Connaisseur : Ne le jetez pas tout entier dans l''eau ! Comme la formule est très riche en beurres végétaux, coupez simplement la base effervescente en deux avec un couteau. Vous obtiendrez ainsi la juste dose d''hydratation et de parfum pour profiter de deux bains divinement relaxants.', '', '["b4993264-edb4-4a52-ad9c-ce06386fcae3", "90ee255d-e46d-4700-9401-e15ff5d362ec"]', 'Fondant de Bain Hydratant Cupcake - 9 Parfums | Kavern', 'Craquez pour nos fondants de bain façon cupcakes. Base effervescente, crème hydratante aux beurres de cacao et karité. Un soin pour 2 bains.', '{"fondant de bain cupcake","boule de bain effervescente","bombe de bain beurre karité cacao","cosmétique bain artisanal europe","idée cadeau bain femme","cupcake bain hydratant"}', false, 0, NULL, NULL, NULL, NULL, 20),
	('b014b3e8-5875-4fba-93cc-347062ede10b', NULL, 'Gant Démaquillant Magique "Nuage Pur" en Microfibre Hypoallergénique', 'gant-demaquillant-magique-nuage-pur-en-microfibre-hypoallergenique', 0, 3.9, NULL, NULL, 'Et si le meilleur démaquillant du monde était tout simplement... l''eau claire ? Chez Kavern, nous aimons bousculer vos habitudes avec des trouvailles inattendues. Fini les cotons polluants, les laits démaquillants coûteux et les lotions qui irritent les peaux sensibles.<div><br></div><div>Fabriqué avec une microfibre d''une douceur exceptionnelle, le gant "Nuage Pur" agit comme un véritable aimant. Il accroche les particules de maquillage (même tenaces) et nettoie vos pores en profondeur en un seul geste. Hypoallergénique et respectueux de tous les types de peau, il transforme l''épreuve du démaquillage en un pur moment de douceur.</div><div><br></div><div>Pensé pour durer, il est lavable en machine à 30°C et réutilisable à l''infini. Une petite révolution zéro déchet pour votre salle de bain, votre peau, et votre portefeuille !</div>', 'Le secret d''une peau nette, juste avec de l''eau ! Dites adieu aux cotons et lotions chimiques avec ce gant écologique, économique et ultra-doux.', 'https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772016276212-ug10ug.webp', NULL, '[]', '["https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772016276902-m3wyn.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772016276130-o8y2k.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772016276156-8ob1vc.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1772016276069-5ch3jo.webp"]', '{"0494dad3-094b-46dc-a8da-3b5b939c1894": ["Détente & Spa"], "0c8f0d36-16bd-4bbf-811a-5f4ff0f9f103": ["Lavable en machine à 30°C"], "306e8518-134c-49fd-81ea-50576a2bb9b0": ["Trouvaille du Monde"], "493f6faa-b3f4-4336-9734-c981adbe8293": ["Tous types de peau"], "8c90c2de-6a60-4c28-835d-e9f107a28928": ["Microfibre"], "bac19f1b-77b1-496e-8f78-604fe43928c5": ["À moins de 10 €", "Nouveauté"]}', 10, 'instock', true, NULL, '{}', true, false, false, false, 'default', false, false, 'publish', '[]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-02-25 10:45:13.312511+00', '2026-02-25 11:10:20.254+00', false, 'simple', 0, NULL, NULL, 15, 1.75, 'Quand on m''a dit qu''il suffisait de passer ce gant sous l''eau tiède pour enlever du mascara, j''étais sceptique... Et pourtant, la magie opère ! C''est typiquement la pépite Kavern par excellence : un produit malin qui facilite le quotidien. Vous allez faire des économies incroyables en arrêtant d''acheter des bouteilles de démaquillant et des disques en coton tous les mois. Mon conseil : passez-le en machine une première fois avant de l''utiliser pour optimiser la douceur de sa microfibre.', '', '[]', 'Gant Démaquillant Eau Microfibre Lavable | Nuage Kavern', 'Révolutionnez votre routine avec ce gant démaquillant magique en microfibre. Hypoallergénique, il démaquille juste à l''eau ! Lavable et zéro déchet.', '{"gant démaquillant eau","démaquillant microfibre","gant démaquillant lavable","zéro déchet beauté","démaquillant peau sensible","alternative coton","gant hypoallergénique","soin visage naturel"}', false, 0, NULL, NULL, NULL, NULL, 20),
	('fce6c1fe-4a65-45b1-a393-9ef8bafd4212', NULL, 'Collier Double Rang "Éclat Boréal" en Acier Inoxydable', 'collier-double-rang-eclat-boreal-en-acier-inoxydable', 0, 11.9, NULL, NULL, 'Dans l''univers de la bijouterie, la magie opère souvent lorsque les contraires s''attirent. C''est exactement ce que propose le collier "Éclat Boréal". Nous avons déniché pour vous cette pièce maîtresse qui marie la force de caractère d''une maille plate (dite "serpent") à la délicatesse absolue d''une fleur aux pétales cristallins.<div><br><div>​Oubliez le casse-tête de la superposition : le layering est déjà pensé et parfaitement équilibré. Forgé dans un acier inoxydable de première qualité, ce collier est conçu pour résister au temps, à l''eau et à votre quotidien sans jamais perdre de son éclat. Que ce soit sur un simple t-shirt blanc ou pour sublimer une robe de soirée, il est la touche d''inattendu qui fera toute la différence.</div></div>', 'Illuminez votre décolleté avec l''alliance parfaite d''une maille serpent audacieuse et d''une fleur scintillante. L''élégance sans effort.', 'https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1771709900891-8uz1v6.webp', NULL, '[]', '["https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1771709900889-hic8ub.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1771709900086-snrwvk.webp"]', '{"Couleur": ["Or", "Argent"], "0494dad3-094b-46dc-a8da-3b5b939c1894": ["Quotidien Chic", "Soirée Élégante"], "306e8518-134c-49fd-81ea-50576a2bb9b0": ["Trouvaille du Monde"], "8c90c2de-6a60-4c28-835d-e9f107a28928": ["Acier Inoxydable"], "bac19f1b-77b1-496e-8f78-604fe43928c5": ["Le Coup de ❤️ d''André"], "df5227cd-8f2d-426b-8fa6-1fa315e04f87": ["💧 Résiste à l''eau (Waterproof)"]}', 0, 'instock', false, NULL, '{}', true, false, false, false, 'default', true, false, 'publish', '[]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-02-21 21:41:26.420767+00', '2026-02-25 08:26:33.881+00', false, 'simple', 0, NULL, NULL, 2, 4.8, 'Ce qui m''a immédiatement fait craquer pour cette pépite, c''est la façon dont la maille plate capte la lumière et épouse la peau. C''est un bijou qui a une vraie ''présence'' sans être lourd. Un indispensable de la Kavern que je vous recommande les yeux fermés !', '', '[]', 'Collier Double Rang Acier Inoxydable Pendentif Fleur | Kavern', 'Craquez pour ce collier double rang en acier inoxydable pour femme. Maille serpent et pendentif fleur scintillante. Résiste à l''eau. Expédition rapide.', '{"collier acier inoxydable femme","collier double rang","collier layering","bijou fleur cristal","collier maille serpent","collier anti-ternissement","bijou créateur Kavern."}', false, 0, NULL, NULL, NULL, NULL, 20),
	('21ea2131-8086-4f43-9c41-11984b8b0e8f', NULL, 'Bracelet Élastique "Aura Marbrée" en Acrylique Tubulaire', 'bracelet-elastique-aura-marbree-en-acrylique-tubulaire', 0, 6, NULL, NULL, 'L''inattendu se cache souvent dans ces petits détails qui transforment une tenue basique en un look mémorable. Avec la collection "Aura Marbrée", nous avons déniché l''accessoire parfait pour réveiller votre poignet. Fabriqué en acrylique de qualité, chaque maillon tubulaire révèle des nuances profondes rappelant la pierre naturelle ou la résine des années 70.<div><br></div><div>Ponctué de délicats anneaux dorés qui accrochent la lumière, ce bracelet se glisse en un clin d''œil grâce à son élastique ultra-résistant et confortable. Mais attention, son charme est redoutable : une fois que vous en aurez essayé un, vous aurez envie de tous les collectionner pour créer des combinaisons uniques au gré de vos envies !</div><div><br></div><div>​Le contraste parfait : Associez-les à notre [Collier Double Rang "Éclat Boréal"] pour mixer la chaleur de l''acrylique avec la brillance de l''acier inoxydable.</div>', 'Craquez pour l''allure rétro-chic de ce bracelet tubulaire aux reflets marbrés. La touche de couleur audacieuse à accumuler sans modération !', 'https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1771711969083-qzwsn9.webp', NULL, '[]', '["https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1771711969148-53lscx.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1771711968484-1ky03p.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1771711969092-ips79b.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1771711969062-q3b1h.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1771711968292-y38z2l.webp", "https://dckbrlxqmgfzaacxqiio.supabase.co/storage/v1/object/public/media/1771711969083-ufyqv5.webp", "https://dckbrlxqmgfzaacxqiio.supa